export function getOpportunityBySlug(slug: string): Opportunity | undefined {
  return opportunities.find((o) => o.slug === slug);
}

export function getSimilarOpportunities(opportunity: Opportunity): Opportunity[] {
  return opportunity.similarSlugs
    .map((slug) => getOpportunityBySlug(slug))
    .filter((o): o is Opportunity => Boolean(o))
    .slice(0, 5);
}
